  <script>
    const categories = ["Profile","Wallet","Welcome","Account Setup","Home","Subscription & Paywall","Login","Settings","Checkout","Collections"];
    const tabs = ["Screens","UI Elements","Flows","Text in Screenshot"];
    const grid = document.getElementById('resultGrid');
    const filtersWrap = document.querySelector('.filters');

    let activeTab = tabs[0];
    let activeCategory = categories[0];

    function makeShots(tab, category) {
      return Array.from({ length: 8 }, (_, i) => `${tab} · ${category} · ${i + 1}`);
    }

    function renderFilters() {
      filtersWrap.innerHTML = '';
      categories.forEach(cat => {
        const btn = document.createElement('button');
        btn.className = 'pill' + (cat === activeCategory ? ' active' : '');
        btn.textContent = cat;
        btn.type = 'button';
        btn.addEventListener('click', () => {
          activeCategory = cat;
          renderFilters();
          renderGrid();
        });
        filtersWrap.appendChild(btn);
      });
    }

    function renderGrid() {
      grid.classList.add('switching');
      setTimeout(() => {
        grid.innerHTML = '';
        makeShots(activeTab, activeCategory).forEach(label => {
          const card = document.createElement('div');
          card.className = 'shot';
          card.dataset.label = label;
          grid.appendChild(card);
        });
        grid.classList.remove('switching');
      }, 140);
    }

    document.querySelectorAll('.tab').forEach(btn => {
      btn.addEventListener('click', () => {
        activeTab = btn.dataset.tab;
        document.querySelectorAll('.tab').forEach(t => {
          t.classList.remove('active');
          t.setAttribute('aria-selected', 'false');
        });
        btn.classList.add('active');
        btn.setAttribute('aria-selected', 'true');
        renderGrid();
      });
    });

    renderFilters();
    renderGrid();

    const stage = document.getElementById('flowStage');
    const flowModes = {
      videos: ['Onboarding Clip','Paywall Clip','Checkout Clip','Upgrade Clip','Empty State Clip','Success Clip'],
      prototype: ['Step 1: Open','Step 2: Input','Step 3: Confirm','Step 4: Review','Step 5: Pay','Step 6: Complete']
    };

    function renderFlow(mode = 'videos') {
      stage.innerHTML = '';
      flowModes[mode].forEach(step => {
        const box = document.createElement('div');
        box.className = 'mini';
        box.dataset.step = step;
        stage.appendChild(box);
      });
    }

    document.querySelectorAll('.toggle button').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.toggle button').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        renderFlow(btn.dataset.flow);
      });
    });

    renderFlow();

    const counters = document.querySelectorAll('[data-counter]');
    let counted = false;

    function formatNum(n) { return n.toLocaleString(); }

    function animateCounter(el, target, delay = 0) {
      const start = performance.now() + delay;
      const duration = 1200;
      function tick(now) {
        if (now < start) { requestAnimationFrame(tick); return; }
        const progress = Math.min((now - start) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        el.textContent = formatNum(Math.floor(target * eased));
        if (progress < 1) requestAnimationFrame(tick);
      }
      requestAnimationFrame(tick);
    }

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting && !counted) {
          counted = true;
          counters.forEach((el, i) => animateCounter(el, Number(el.dataset.counter), i * 160));
          observer.disconnect();
        }
      });
    }, { threshold: 0.38 });

    observer.observe(document.getElementById('stats'));

    const testimonials = [
      ['"My absolute favorite resource for finding mobile and web app references!"', 'Sebastian Speier — Product Designer'],
      ['"A giant time-saver for product teams. The flow examples are gold."', 'Meng To — Founder'],
      ['"I use ScreenVault daily to benchmark patterns and speed up ideation."', 'Marco Cornacchia — Senior Designer'],
      ['"A must-have tool for product designers and UX researchers."', 'Daryl Ginn — Product Lead'],
      ['"The searchable screenshot library is incredibly deep and practical."', 'Rachel How — Design Manager'],
      ['"Copy-to-Figma + collections made our workflow dramatically faster."', 'Haerin Song — Staff Product Designer']
    ];

    function buildMarquee(rowId, reverse = false) {
      const row = document.getElementById(rowId);
      const feed = reverse ? [...testimonials].reverse() : testimonials;
      const all = [...feed, ...feed];
      row.innerHTML = all.map(([quote, who]) => `\n        <article class="testi-card">\n          <p>${quote}</p>\n          <div class="who">${who}</div>\n        </article>`).join('');
    }

    buildMarquee('row1');
    buildMarquee('row2', true);

    const iconsA = document.getElementById('iconsA');
